/* Visual layer only: world coordinates, collision boxes and route logic live in game.js. */
const storyArt={};
if(typeof Image!=='undefined')for(const [name,file] of Object.entries({valley:'valley.jpg',cottage:'cottage.png',teacher:'teacher-hd.png',tree:'tree.png'})){const img=new Image();img.src='assets/storybook/'+file;storyArt[name]=img}
function artReady(name){return storyArt[name]?.complete&&storyArt[name].naturalWidth>0}
function noise(n){return (Math.sin(n*127.1+311.7)*43758.5453)%1*.5+.5}
function blendGradient(x,y,h,colors){const g=c.createLinearGradient(x,y,x,y+h);colors.forEach((v,i)=>g.addColorStop(i/(colors.length-1),v));return g}
function daisy(x,y,s=1,pink=false){c.save();c.translate(x,y);c.scale(s,s);c.strokeStyle='#718845';c.lineWidth=1.8;c.beginPath();c.moveTo(0,9);c.quadraticCurveTo(-1,3,0,-2);c.stroke();for(let j=0;j<5;j++)ellipse(Math.cos(j*1.256)*4,Math.sin(j*1.256)*4,3.8,2.7,pink?'#f4b5ad':'#fff9dd');ellipse(0,0,2.5,2.5,'#edba54');c.restore()}
function leaf(x,y,scale,angle,color){c.save();c.translate(x,y);c.rotate(angle);ellipse(0,0,scale*2,scale,color);c.restore()}
function vine(x,y,len,seed){c.save();c.strokeStyle='#7e974e';c.lineWidth=2;c.beginPath();c.moveTo(x,y);c.bezierCurveTo(x-9,y+len*.3,x+12,y+len*.65,x-5,y+len);c.stroke();for(let i=7;i<len;i+=10){const xx=x+Math.sin(i*.12)*5;leaf(xx+(i%20?4:-3),y+i,3.4,i%20?-.7:.7,['#8fb45c','#6c9c53','#abc36a'][Math.floor(i/10)%3])}if(seed%3===0)daisy(x-4,y+len*.6,.6);c.restore()}
function storyTree(x,y,s=1){if(artReady('tree')){c.drawImage(storyArt.tree,x-69*s,y-147*s,138*s,152*s);return;}c.save();c.translate(x,y);c.scale(s,s);c.strokeStyle='#7d7148';c.lineWidth=13;c.lineCap='round';c.beginPath();c.moveTo(0,0);c.quadraticCurveTo(-7,-41,3,-84);c.stroke();c.lineWidth=6;c.beginPath();c.moveTo(-1,-35);c.lineTo(-27,-62);c.moveTo(0,-48);c.lineTo(27,-78);c.stroke();for(let i=0;i<17;i++){const a=i*2.4,rad=15+noise(i+4)*20;ellipse(Math.cos(a)*rad,-91+Math.sin(a)*rad,19+noise(i+2)*11,25,['#478766','#55986a','#70a66b','#87b66e','#a6bd76'][i%5])}c.strokeStyle='#b39a65';c.lineWidth=2;c.beginPath();c.moveTo(-3,-4);c.lineTo(-4,-30);c.stroke();c.restore()}
function fence(x,y,w){c.save();c.strokeStyle='#866343';c.lineWidth=3;rr(x,y-19,w,6,2,'#a78252');rr(x,y-8,w,5,2,'#b98c56');for(let xx=x;xx<x+w;xx+=28){rr(xx,y-29,8,30,3,'#aa7949');rr(xx+1,y-28,2,26,1,'#dab47a');ellipse(xx+4,y-17,1.4,1.4,'#74573d')}c.restore()}
function lantern(x,y){c.save();c.translate(x,y);c.strokeStyle='#81683d';c.lineWidth=4;c.beginPath();c.moveTo(0,0);c.lineTo(0,-75);c.quadraticCurveTo(1,-85,13,-81);c.stroke();const light=c.createRadialGradient(12,-64,1,12,-64,27);light.addColorStop(0,'#fff3a365');light.addColorStop(1,'#fff3a300');ellipse(12,-64,27,27,light);rr(4,-78,18,26,4,'#a17b42');rr(7,-74,12,18,2,blendGradient(0,-74,18,['#fff9d2','#ffce72']));c.fillStyle='#77593b';c.beginPath();c.moveTo(0,-78);c.lineTo(13,-88);c.lineTo(26,-78);c.fill();c.strokeStyle='#bb9859';c.lineWidth=1.8;c.beginPath();c.moveTo(13,-74);c.lineTo(13,-56);c.stroke();c.restore()}
const platformArtSeeds=new WeakMap();
function platformArtSeed(platform){if(!platformArtSeeds.has(platform))platformArtSeeds.set(platform,Math.floor(platform.x));return platformArtSeeds.get(platform)}
function paintPlatform(platform){if(platform.x+platform.w<camera-100||platform.x>camera+W+100)return;if(routeMode==='cloud'){cloud(platform.x+platform.w/2,platform.y+27,platform.w/82);return}
 const artSeed=platformArtSeed(platform),b={...platform,x:0,y:0};
 const cave=routeMode==='tunnel',floating=b.h<50,depth=floating?45:Math.max(b.h,H-platform.y+14),y=0;c.save();c.translate(platform.x,platform.y);
 c.fillStyle=blendGradient(0,y,depth,cave?['#b96c47','#794538','#503342']:['#dbb17e','#bd8e63','#a77b59']);c.beginPath();c.moveTo(b.x+5,y+4);c.lineTo(b.x+b.w-5,y+4);c.quadraticCurveTo(b.x+b.w+7,y+20,b.x+b.w-8,y+depth-8);if(floating){c.lineTo(b.x+b.w*.6,y+depth);c.lineTo(b.x+b.w*.53,y+depth+9);c.lineTo(b.x+b.w*.4,y+depth);c.lineTo(b.x+13,y+depth-6)}else c.lineTo(b.x,y+depth);c.closePath();c.fill();
 c.save();c.clip();for(let row=0;row<depth/31;row++)for(let i=0;i<b.w/47+1;i++){const xx=b.x+i*48+(row%2?19:0),yy=y+24+row*31,n=noise(Math.floor(xx)+row+artSeed),w=19+n*13,h=10+noise(row+i)*9;c.fillStyle=row%2?'#e6bf9166':'#976d4b22';c.beginPath();c.moveTo(xx-w,yy-2);c.quadraticCurveTo(xx-w+3,yy-h,xx-4,yy-h);c.lineTo(xx+w*.6,yy-h+3);c.quadraticCurveTo(xx+w+5,yy-2,xx+w*.7,yy+h*.6);c.lineTo(xx-5,yy+h);c.lineTo(xx-w,yy+5);c.closePath();c.fill();c.strokeStyle='#efc99e44';c.lineWidth=1.1;c.beginPath();c.moveTo(xx-w+3,yy-5);c.quadraticCurveTo(xx-5,yy-h-1,xx+w*.5,yy-h+4);c.stroke();if(n>.66){c.fillStyle='#815e4230';c.beginPath();c.moveTo(xx+8,yy+6);c.lineTo(xx+16,yy+10);c.lineTo(xx+13,yy+16);c.fill()}}c.restore();
 // The grassy ridge follows the collision surface exactly; its fringe hangs below it.
 rr(b.x-2,y,b.w+4,19,8,cave?'#c47a4f':'#517f49');for(let xx=b.x+3;xx<b.x+b.w;xx+=12)ellipse(xx,y+12,9,8,cave?'#df9b5d':'#6c9b4d');
 rr(b.x,y-4,b.w,12,6,blendGradient(0,y-4,14,cave?['#efb775','#b97247']:['#c3d877','#8db34f']));
 for(let xx=b.x+7;xx<b.x+b.w-2;xx+=15){const n=noise(Math.floor(xx)+artSeed);c.strokeStyle=cave?'#e2a268':n>.65?'#e2e89b':'#a7c66a';c.lineWidth=2;c.beginPath();c.moveTo(xx,y+2);c.lineTo(xx-2,y-4-n*5);c.moveTo(xx+3,y+2);c.lineTo(xx+6,y-3-n*4);c.stroke()}
 if(!cave){for(let xx=b.x+20;xx<b.x+b.w-12;xx+=61){const seed=Math.floor(xx)+artSeed;if(noise(seed)>.55)daisy(xx,y-9,.45+noise(seed+1)*.4,seed%4===0)}if(floating||b.w>300){vine(b.x+b.w-16,y+15,floating?32:63,artSeed);if(b.w>150)vine(b.x+24,y+17,floating?24:47,artSeed+1)}}c.restore()
}
function storyBackground(){const img=storyArt.valley;if(artReady('valley'))c.drawImage(img,-camera*.105,0,W+600,H);else{c.fillStyle=blendGradient(0,0,H,['#8dd9f6','#d8f4f2']);c.fillRect(0,0,W,H)}
 // Warm glowing sun, a tiny face and drifting birds are animated independently.
 const sx=W-140-camera*.017,sy=79;const halo=c.createRadialGradient(sx,sy,20,sx,sy,65);halo.addColorStop(0,'#fff4b24d');halo.addColorStop(1,'#fff4b200');ellipse(sx,sy,65,65,halo);ellipse(sx,sy,32,33,'#fff4bc');ellipse(sx,sy,28,29,blendGradient(0,sy-28,58,['#fff0a2','#ffe18a']));ellipse(sx-10,sy+1,2.2,2.7,'#bb8f59');ellipse(sx+10,sy+1,2.2,2.7,'#bb8f59');ellipse(sx-15,sy+8,4,2.3,'#f2bd88');ellipse(sx+15,sy+8,4,2.3,'#f2bd88');c.strokeStyle='#bb8f59';c.lineWidth=1.5;c.beginPath();c.arc(sx,sy+6,3,0,Math.PI);c.stroke();ellipse(sx+12,sy-15,3,5,'#fff9da');
 c.strokeStyle='#fff9e4';c.lineWidth=3;c.lineCap='round';for(let i=0;i<4;i++){const x=(i*217+frame*.11)% (W+100)-45,y=65+(i%3)*35;c.beginPath();c.moveTo(x-5,y-2);c.quadraticCurveTo(x,y+4,x+5,y-2);c.stroke()}
 c.save();c.translate(-camera,0);for(let i=0;i<17;i++){const x=220+i*298;if(x<camera-90||x>camera+W+90)continue;const onGround=platforms.some(p=>p.h>50&&x>p.x+20&&x<p.x+p.w-40);if(!onGround)continue;storyTree(x,500,.64+noise(i)*.33);fence(x+20,500,67);if(i%2===0)lantern(x-38,500)}c.restore()
}
function storyEdges(){if(routeMode!=='main')return;c.save();c.globalAlpha=.9;for(let side=0;side<2;side++){c.save();c.translate(side?W:0,0);c.scale(side?-1:1,1);c.strokeStyle='#756743';c.lineWidth=16;c.beginPath();c.moveTo(-20,74);c.quadraticCurveTo(37,35,108,-15);c.stroke();for(let i=0;i<12;i++)ellipse(i*11-15,-3+Math.sin(i*1.6)*14,22,21,['#39775f','#4e8e68','#6b9e6e'][i%3]);c.restore()}
 // Foreground flowers sit below the playable ridge and never hide feet.
 c.globalAlpha=.9;for(let i=0;i<15;i++){const x=(i*107-camera*.22)%(W+140);ellipse(x,H+9,37,24,'#427e60');leaf(x+14,H-9,11,-.9,'#6a9e68');if(i%2===0)daisy(x+8,H-12,1.2,i%3===0)}c.restore()
}
function paintCollectible(s){const bob=Math.sin(frame*.045+(s.movingPlatform?s.moveOffsetX:s.x))*3,sy=s.y+bob,r=18;c.save();c.shadowColor='#f4c45444';c.shadowBlur=9;star(s.x,sy,r+2,'#fff9df');c.shadowBlur=0;star(s.x,sy,r,'#ca8d3c');star(s.x,sy-1,r-2,blendGradient(0,sy-r,r*2,['#fff0a7','#ffd264','#eead45']));c.strokeStyle='#fff7c8';c.lineWidth=1;c.beginPath();c.moveTo(s.x-10,sy-3);c.lineTo(s.x-5,sy-4);c.lineTo(s.x-1,sy-13);c.stroke();c.font='800 13px "Noto Sans Thai",sans-serif';c.textAlign='center';c.textBaseline='middle';c.lineWidth=2;c.strokeStyle='#fff3cd';c.strokeText(s.lesson.glyph,s.x,sy+1);c.fillStyle='#704326';c.fillText(s.lesson.glyph,s.x,sy+1);c.restore()}
function storyHouse(){if(!artReady('cottage'))return false;c.drawImage(storyArt.cottage,-48,265,260,242);c.save();c.fillStyle='#fff6df';c.textAlign='center';c.font='700 13px "Noto Sans Thai",sans-serif';c.shadowColor='#75452e';c.shadowBlur=2;c.fillText('บ้านของเรา',101,399);c.restore();return true}
function storyHero(x,y,scale){if(!artReady('teacher'))return false;c.save();c.translate(x+16,y+58);c.scale(player.dir*scale,scale);const walking=player.ground&&Math.abs(player.vx)>.5,bob=walking?Math.abs(Math.sin(frame*.24))*2:Math.sin(frame*.04)*.4;c.rotate(walking?Math.sin(frame*.24)*.035:!player.ground?-.06:0);ellipse(0,1,18,4,'#304f3433');const heroHeight=80,heroWidth=heroHeight*storyArt.teacher.naturalWidth/storyArt.teacher.naturalHeight;c.imageSmoothingQuality='high';c.drawImage(storyArt.teacher,-heroWidth/2,-heroHeight-bob,heroWidth,heroHeight);if(weaponPower){star(-16,-32,7,'#f5d57f',frame*.03)}
 if(attack>5){const phase=(attackMax-attack)/(attackMax-5),angle=-1.6+phase*2.8,len=55+Math.sin(phase*Math.PI)*(weaponPower?64:34);c.save();c.translate(20,-15);c.rotate(angle);c.fillStyle=blendGradient(0,-7,15,['#78c4ba','#287c78','#195b58']);c.beginPath();c.moveTo(0,-3);c.lineTo(len-13,-7);c.lineTo(len+1,0);c.lineTo(len-13,8);c.lineTo(0,3);c.closePath();c.fill();c.save();c.clip();c.strokeStyle='#ffe2a1';c.lineWidth=3;for(let i=7;i<len;i+=13){c.beginPath();c.moveTo(i,-10);c.lineTo(i-8,11);c.stroke()}c.restore();ellipse(0,0,4,4,'#f6cca4');star(len+3,-1,5,'#fff6bb',phase);c.restore();c.strokeStyle='#fff9d9bb';c.lineWidth=2;c.beginPath();c.arc(20,-15,len*.7,-1.4,angle);c.stroke()}c.restore();return true}
function storySlime(e){if(['wing','dragon'].includes(e.kind))return false;const bob=Math.sin(frame*.12+e.x)*1.3;c.save();c.translate(e.x,e.y+bob);const angry=e.kind==='runner'||e.kind==='charger';ellipse(e.w/2,e.h+3,22,4,'#56704a33');ellipse(9,e.h-1,7,4,'#6b6278');ellipse(e.w-9,e.h-1,7,4,'#6b6278');const color=angry?['#f5b4a1','#e28e91','#b56c8a']:['#dfbbf4','#bb93df','#9774c0'];rr(0,0,e.w,e.h,14,blendGradient(0,0,e.h,color));c.strokeStyle=angry?'#b86c77':'#9870b2';c.lineWidth=1;c.stroke();ellipse(9,7,5,3,'#fff5e866');for(const xx of [11,e.w-11]){ellipse(xx,13,3,4,'#5e4168');ellipse(xx-.8,11.5,.8,1.1,'#fff8e4')}ellipse(5,22,4,2.5,'#efadbb');ellipse(e.w-5,22,4,2.5,'#efadbb');c.strokeStyle='#754575';c.lineWidth=1.7;c.beginPath();c.moveTo(16,23);c.quadraticCurveTo(19,27,21,23);c.quadraticCurveTo(24,27,26,23);c.stroke();if(angry){c.lineWidth=2;c.beginPath();c.moveTo(6,5);c.lineTo(15,8);c.moveTo(e.w-6,5);c.lineTo(e.w-15,8);c.stroke()}if(angry&&Math.abs(e.x-player.x)<150){ellipse(e.w/2,-14,9,9,'#fffaf0');c.fillStyle='#bc795b';c.font='bold 12px Outfit';c.textAlign='center';c.fillText('!',e.w/2,-10)}c.restore();return true}
